import {analyzeOwner,shiftDate,REVENUE_TYPES,EXTERNAL_OUT_TYPES,SERVICE_TYPES} from './owner-metrics.js?v=7';
import {TYPES,METHODS,csvCell} from './core.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>n===null?'—':new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:n%100?2:0}).format(n/100);
const shortDate=d=>new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'2-digit',month:'short'});
const period=(a,b)=>`${shortDate(a)}${a.slice(0,4)!==b.slice(0,4)?' '+a.slice(0,4):''} — ${shortDate(b)} ${b.slice(0,4)}`;
export function initOwner({getData,getDate}){
 const root=document.querySelector('#owner-view');let selected=null;
 root.innerHTML='<div class="owner-filter"><label>Период<select id="owner-preset"><option value="month">С начала месяца</option><option value="today">День тетради</option><option value="week">7 дней</option><option value="all">Все записи</option><option value="custom">Свой период</option></select></label><div class="owner-dates"><label>С<input id="owner-from" type="date"></label><label>По<input id="owner-to" type="date"></label></div><button id="owner-export" type="button">↓ CSV</button></div><p id="owner-scope" class="owner-scope"></p><div id="owner-error" role="alert"></div><div id="owner-content"></div>';
 const $=s=>root.querySelector(s);const preset=$('#owner-preset'),from=$('#owner-from'),to=$('#owner-to');
 const dialog=document.createElement('dialog');dialog.id='owner-detail';dialog.innerHTML='<div class="modal-head"><h2 id="owner-detail-title"></h2><button id="owner-detail-close" class="icon-btn" aria-label="Закрыть детализацию">×</button></div><div id="owner-detail-body"></div>';document.body.append(dialog);dialog.querySelector('#owner-detail-close').onclick=()=>dialog.close();
 function choose(){const anchor=getDate(),data=getData();let start=anchor,end=anchor;
  if(preset.value==='month')start=anchor.slice(0,7)+'-01';
  if(preset.value==='week')start=shiftDate(anchor,-6);
  if(preset.value==='all'){const dates=[...Object.keys(data.days),...data.entries.map(e=>e.date)].sort();start=dates[0]||anchor;end=dates.at(-1)||anchor;}
  if(preset.value!=='custom'){from.value=start;to.value=end;}
 }
 function detail(title,rows){dialog.querySelector('#owner-detail-title').textContent=title;dialog.querySelector('#owner-detail-body').innerHTML='<p class="owner-detail-count">'+rows.length+' записей · '+period(selected.from,selected.to)+'</p>'+recordsTable(rows);dialog.showModal();}
 function recordsTable(rows){return rows.length?'<div class="owner-table-scroll"><table><thead><tr><th>Дата</th><th>Операция / наименование</th><th>Оплата</th><th>Сумма</th></tr></thead><tbody>'+rows.map(e=>'<tr><td>'+esc(e.date)+'<small>'+esc(e.time)+'</small></td><td>'+esc(e.title)+'<small>'+esc(TYPES[e.type][0])+(e.manager?' · '+esc(e.manager):'')+'</small></td><td>'+e.payments.map(p=>esc(METHODS[p.method])+' '+money(p.amount)).join('<br>')+'</td><td>'+money(e.amount)+'</td></tr>').join('')+'</tbody></table></div>':'<p class="owner-empty">Нет записей для этой детализации.</p>';}
 function bars(items){const max=Math.max(1,...items.map(i=>i.amount));return '<div class="owner-bars">'+items.map(i=>'<button type="button" data-owner-group="'+i.key+'"><span>'+i.label+'</span><strong>'+money(i.amount)+'</strong><span class="owner-bar-track"><span style="width:'+Math.max(0,i.amount/max*100)+'%"></span></span></button>').join('')+'</div>';}
 function chart(days){if(!days.length)return '<p class="owner-empty">Нет отмеченных дней в этом периоде.</p>';
  const W=640,H=220,L=65,R=20,T=20,B=40,min=Math.min(0,...days.map(d=>d.netRevenue)),max=Math.max(100,...days.map(d=>d.netRevenue)),span=max-min;
  const earliest=Date.parse(selected.from),latest=Date.parse(selected.to),x=d=>L+(latest===earliest?.5:(Date.parse(d)-earliest)/(latest-earliest))*(W-L-R),y=v=>T+(max-v)/span*(H-T-B);
  let path='',last=null;for(const d of days){path+=(last&&shiftDate(last,1)===d.date?'L':'M')+x(d.date).toFixed(1)+' '+y(d.netRevenue).toFixed(1)+' ';last=d.date;}
  const ticks=[min,(max+min)/2,max];const grid=ticks.map(v=>'<line x1="'+L+'" x2="'+(W-R)+'" y1="'+y(v)+'" y2="'+y(v)+'"/><text x="'+(L-7)+'" y="'+(y(v)+4)+'" text-anchor="end">'+new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(v/100)+'</text>').join('');
  const points=days.map(d=>'<circle role="button" tabindex="0" aria-label="'+esc(shortDate(d.date)+': '+money(d.netRevenue))+'" data-owner-day="'+d.date+'" cx="'+x(d.date)+'" cy="'+y(d.netRevenue)+'" r="4.5"><title>'+esc(shortDate(d.date)+' · '+money(d.netRevenue))+'</title></circle>').join('');
  return '<div class="owner-chart"><svg viewBox="0 0 640 220" role="group" aria-label="Выручка за вычетом возвратов по дням, рубли"><g class="owner-grid">'+grid+'</g><path class="owner-line" d="'+path+'"/>'+points+'<text x="'+L+'" y="210">'+esc(shortDate(selected.from))+'</text><text x="'+(W-R)+'" y="210" text-anchor="end">'+esc(shortDate(selected.to))+'</text></svg></div><p class="owner-chart-note">₽ · Нажмите точку, чтобы открыть записи дня. Дни без записей в тетради не соединяются линией.</p>';
 }
 function comparison(key){if(!selected.comparable)return '';const before=selected.previous[key],now=selected.current[key];if(before===0)return '<small class="owner-compare">Ранее: '+money(before)+' · процент не рассчитывается</small>';const pct=(now-before)/Math.abs(before)*100;return '<small class="owner-compare">'+(pct>0?'+':'')+pct.toLocaleString('ru-RU',{maximumFractionDigits:1})+'% к предыдущему периоду</small>';}
 function render(){try{selected=analyzeOwner(getData(),from.value,to.value);$('#owner-error').textContent='';}catch(e){$('#owner-error').textContent=e.message;$('#owner-content').innerHTML='';return;}
  const a=selected,m=a.current;$('#owner-scope').textContent=period(a.from,a.to)+' · '+a.rows.length+' записей · отмечено '+a.coverage.days+' из '+a.coverage.expected+' календарных дней';
  if(!a.rows.length&&!a.dates.length){$('#owner-content').innerHTML='<div class="owner-empty-state"><span>▥</span><h2>За этот период записей нет</h2><p>Выберите другой период или добавьте записи в тетрадь. Дашборд обновится автоматически.</p><button id="owner-all" type="button">Показать все записи</button></div>';$('#owner-all').onclick=()=>{preset.value='all';choose();render();};return;}
  const cards=[['netRevenue','Выручка после возвратов',m.netRevenue,'Выручка продаж и услуг − возвраты','net'],['sales','Продажи',m.sales,'Шины, пакеты и прочие продажи','sales'],['services','Услуги',m.services,'Шиномонтаж, правка и утилизация','services'],['externalOut','Внешние выплаты',m.externalOut,'Без инкассации; включает закупки и возвраты','out']];
  const risks=[...a.discrepancies.map(d=>({date:d.date,text:'Касса '+shortDate(d.date)+': факт отличается от расчета на '+money(d.difference)+'. Проверьте оплаты и выплаты.'})),...a.negativeCash.map(d=>({date:d.date,text:'Отрицательная касса '+shortDate(d.date)+': '+money(d.ending)+'. Проверьте начальный остаток.'}))];
  $('#owner-content').innerHTML='<div class="owner-kpis">'+cards.map(([key,label,value,note,group])=>'<button class="owner-kpi" type="button" data-owner-group="'+group+'"><span>'+label+'</span><strong>'+money(value)+'</strong>'+comparison(key)+'<small>'+note+'</small></button>').join('')+'</div>'+
   '<div class="owner-mini"><span>Шин продано <b>'+m.soldQty+' шт.</b></span><span>Записей продажи шин <b>'+m.saleCount+'</b></span><span>Средняя запись продажи <b>'+money(m.averageSale)+'</b></span></div>'+
   (risks.length?'<section class="owner-panel owner-risk"><h2>Требует проверки</h2>'+risks.map(r=>'<button type="button" data-owner-day="'+r.date+'">'+esc(r.text)+' ↗</button>').join('')+'</section>':'')+
   '<section class="owner-panel"><h2>Динамика выручки после возвратов</h2>'+chart(a.byDate)+'<details><summary>Числа по дням</summary><div class="owner-table-scroll"><table><thead><tr><th>Дата</th><th>Продажи и услуги</th><th>Возвраты</th><th>После возвратов</th></tr></thead><tbody>'+a.byDate.map(d=>'<tr><td>'+esc(d.date)+'</td><td>'+money(d.grossRevenue)+'</td><td>'+money(d.refunds)+'</td><td>'+money(d.netRevenue)+'</td></tr>').join('')+'</tbody></table></div></details></section>'+
   '<div class="owner-two"><section class="owner-panel"><h2>Оплата продаж и услуг</h2>'+bars(Object.entries(m.payments).map(([key,amount])=>({key:'pay-'+key,label:METHODS[key],amount})))+'<p class="owner-note">Поступления до возвратов. Всего '+money(m.grossRevenue)+'.</p></section><section class="owner-panel"><h2>На что выплачены деньги</h2>'+bars([{key:'purchase',label:'Закупки',amount:m.purchases},{key:'expense',label:'Расходы и бонусы',amount:m.expenses},{key:'salary',label:'Зарплата',amount:m.salary},{key:'refund',label:'Возвраты',amount:m.refunds}])+'<p class="owner-note">Все способы оплаты. Инкассация '+money(m.collection)+' показана отдельно.</p></section></div>'+
   '<section class="owner-panel"><h2>Наличные</h2><div class="owner-cash"><div><span>Изменение за период</span><strong>'+money(m.cashNet)+'</strong><small>Поступления наличными − выплаты наличными</small></div><div><span>Расчетный остаток '+(a.cash?shortDate(a.cash.date):'')+'</span><strong>'+(a.cash?money(a.cash.calculated):'—')+'</strong><small>'+(a.cash?(a.cash.actual===null?'Фактический пересчет не указан':'Фактически: '+money(a.cash.actual)):'Нет исходного остатка')+'</small></div></div><p class="owner-note">Остаток относится к последнему отмеченному дню периода. Начальные остатки разных дней не суммируются.</p></section>'+
   '<section class="owner-panel"><h2>Сравнение периодов</h2><p class="owner-note">Предыдущий равный период: '+period(a.prior.from,a.prior.to)+'. Закрытых дней: '+a.coverage.previousClosed+' из '+a.coverage.expected+'; текущий: '+a.coverage.closed+' из '+a.coverage.expected+'.</p>'+(a.comparable?'<p>Изменения выручки и выплат показаны в карточках выше.</p>':'<p class="owner-note">Процент изменения не рассчитывается, пока оба периода не заполнены и не закрыты полностью. Отсутствие записей не считается нулевой выручкой.</p>')+'</section>'+
   '<details class="owner-method"><summary>Источник, определения и ограничения</summary><p>Источник — записи тетради в этом браузере. Общей базы сотрудников и подключения к МойСклад нет.</p><p>Средняя запись продажи = сумма записей «Продажа шин» / их количество. Это не средний чек покупателя: одна продажа может быть внесена несколькими записями.</p><p>Внешние выплаты = закупки + расходы и бонусы + зарплата + возвраты. Инкассация — перемещение денег, а внесение — не выручка. Все суммы в рублях.</p><p>Прибыль и маржа недоступны без себестоимости проданных товаров и начисленных расходов. Остатки склада, план-факт и прогноз не рассчитываются: исходных данных нет.</p><p>«Собственник» — экран обзора, отдельная авторизация и ограничение доступа к нему не настроены.</p></details>';
 }
 root.addEventListener('click',event=>{const target=event.target.closest('[data-owner-group],[data-owner-day]');if(!target||!selected)return;
  if(target.dataset.ownerDay){detail('Записи за '+shortDate(target.dataset.ownerDay),selected.rows.filter(e=>e.date===target.dataset.ownerDay));return;}
  const group=target.dataset.ownerGroup,pred={net:e=>REVENUE_TYPES.includes(e.type)||['refund','market'].includes(e.type),sales:e=>['sale','package','other'].includes(e.type),services:e=>SERVICE_TYPES.includes(e.type),out:e=>EXTERNAL_OUT_TYPES.includes(e.type),purchase:e=>e.type==='purchase',expense:e=>['expense','bonus'].includes(e.type),salary:e=>e.type==='salary',refund:e=>['refund','market'].includes(e.type)}[group];
  const rows=group.startsWith('pay-')?selected.rows.filter(e=>REVENUE_TYPES.includes(e.type)&&e.payments.some(p=>p.method===group.slice(4))):selected.rows.filter(pred||(()=>false));detail('Исходные записи',rows);
 });
 root.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key)&&event.target.matches('circle[data-owner-day]')){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
 preset.onchange=()=>{choose();render();};for(const input of [from,to])input.onchange=()=>{preset.value='custom';render();};
 $('#owner-export').onclick=()=>{if(!selected||$('#owner-error').textContent)return;const rows=[['Дата','Время','Операция','Наименование','Количество','Сумма, руб.','Оплаты'],...selected.rows.map(e=>[e.date,e.time,TYPES[e.type][0],e.title,e.qty,(e.amount/100).toFixed(2).replace('.',','),e.payments.map(p=>METHODS[p.method]+' '+money(p.amount)).join(' / ')])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='собственник-'+selected.from+'-'+selected.to+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);};
 choose();return {render,open(){choose();render();}};
}
